def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0\n"

    # If l is 1, start from 2 since 1 is not prime
    if l == 1:
        l = 2

    count = 0

    # We need to find primes in [l, r] that are either 2 or ≡ 1 (mod 4)
    # Use segmented sieve to identify primes in the range

    if r >= 2:
        count = 1 + sum(1 for i in range(l, r + 1) if i % 4 == 1 and is_prime_segmented(l, r, i))
    elif l <= 2:
        count = 1

    def is_prime_segmented(loi, roi, n):
        """Check if n is prime using segmented sieve logic"""
        if n < 2:
            return False

        # For efficiency, check small primes separately
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        if n % 3 == 0:
            return False

        # Trial division up to sqrt(n)
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # For better efficiency with larger ranges, use actual segmented sieve
    if r - l > 3000000:
        # Use the segmented sieve approach
        return count_segmented(l, r)
    else:
        # Direct computation for smaller ranges
        result = 0
        for i in range(l, r + 1):
            if is_prime_segmented(l, r, i):
                if i == 2 or i % 4 == 1:
                    result += 1
        return f"{result}\n"


def count_segmented(l, r):
    """Count primes in [l, r] that are 2 or congruent to 1 mod 4"""

    # Sieve primes up to sqrt(r)
    import math
    sqrt_r = int(math.isqrt(r))
    primes = []
    is_prime = [True] * (sqrt_r + 1)

    for i in range(2, sqrt_r + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, sqrt_r + 1, i):
                is_prime[j] = False

    # Segmented sieve for [l, r]
    if l <= 2:
        l_start = 2
    else:
        l_start = l

    if r < 2:
        return 0

    count = 0

    # Count 2 if in range
    if l_start <= 2 <= r:
        count += 1
        if l > 2:
            l_start = 3

    # Process range in blocks to avoid memory issues
    block_size = min(r - l_start + 1, 1000000)
    offset = 0

    while l_start <= r:
        end = min(l_start + block_size - 1, r)
        seg_len = end - l_start + 1

        is_prime_seg = [True] * seg_len

        for p in primes:
            # Find first multiple of p >= l_start
            start = max(l_start, ((l_start + p - 1) // p) * p)

            if start == p:
                start += p

            if start > end:
                continue

            for j in range(start, end + 1, p):
                is_prime_seg[j - l_start] = False

        # Actually check primality and count
        for i in range(0, seg_len):
            candidate = l_start + i
            if is_prime_seg[i]:
                if candidate == 2 or candidate % 4 == 1:
                    count += 1

        l_start = end + 1

    return count

import collections

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.edge_cnt = 0

    def add_edge(self, u, v, cap, forward_idx=-1):
        self.graph[u].append([v, cap, self.edge_cnt])
        self.graph[v].append([u, 0, self.edge_cnt - 1])
        self.forward_edges[forward_idx] = [u, v, cap]
        self.edge_cnt += 1

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = collections.deque([s])
        while q:
            u = q.popleft()
            for v, cap, rev in self.graph[u]:
                if self.graph[v][rev][1] > 0 and self.level[v] == -1:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] != -1

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        total = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                total += pushed
        return total

