    for i in range(1, n + 1):
        parts = lines[i].split("'")
        if len(parts) >= 2:
            abbreviations.append(parts[1])

    used_suffixes = set()
    abbrev_to_year = {}

    year = 1989
    max_abbrev_len = max((len(a) for a in abbreviations), default=0)

    # Simulation limit - should be sufficient based on problem constraints
    max_iterations = 10**12

    for _ in range(max_iterations):
        year_str = str(year)

        # Get all suffixes of this year (up to max_abbrev_len)
        for length in range(1, max_abbrev_len + 2):
            if len(year_str) >= length:
                suffix = year_str[-length:]
                if suffix not in used_suffixes:
                    used_suffixes.add(suffix)
                    abbrev_to_year[suffix] = year
                    break

        if len(year_str) == len(abbrev_to_year.keys()):
            # Should not happen, but break if we've processed too many years
            break

        year += 1

    results = []
    for abbrev in abbreviations:
        results.append(str(abbrev_to_year.get(abbrev, "")))

    return '\n'.join(results)

def solution(input_data):
    """
    Solve the graph value assignment problem.

    Args:
        input_data: String containing problem input

    Returns:
        String with "YES" and node values, or "NO"
    """
    lines = input_data.strip().split('\n')
    if not lines:
        return "NO"

    first_line = lines[0].split()
    if len(first_line) < 2:
        return "NO"
    N = int(first_line[0])
    M = int(first_line[1])

    # Parse edges
    edges = []
    for i in range(1, M + 1):
        if i < len(lines):
            parts = list(map(int, lines[i].split()))
            if len(parts) == 3:
                edges.append((parts[0], parts[1], parts[2]))
        else:
            break

    # Build adjacency list with edge types
    adj = [[] for _ in range(N + 1)]
    has_boundary = [False] * (N + 1)  # Track if we've found a potential solution path

    for u, v, c in edges:
        adj[u].append((v, c))
        adj[v].append((u, c))

    assignments = {}
    visited = [False] * (N + 1)

    # Check if any solution is possible
    def dfs_check(u, val):
        """Check if we can assign value=val to node u consistently"""
        visited[u] = True
        assignments[u] = val

        total_abs = abs(val)
        for v, c in adj[u]:
            expected_sum = 1 if c == 1 else 2
            if not visited[v]:
                v_val = expected_sum - val
                result = dfs_check(v, v_val)
                if not result:
                    return False
                total_abs += abs(v_val)
            else:
                expected_v = expected_sum - val
                actual_v = assignments[v]
                # Check consistency (within tolerance for floating point)
                if abs(expected_v - actual_v) > 1e-9:
                    total_abs += float('inf')
                else:
                    total_abs += abs(actual_v)
        return True

    try:
        # For each node, try to find a valid assignment
        best_solution = None
        best_total = float('inf')

        for start_node in range(1, N + 1):
            if visited[start_node]:
                continue

            visited = [False] * (N + 1)
            assignments = {}

            # Try different values to minimize L1 norm
            # Use a smarter approach based on component structure

            valid_global = True
            component_sums = []

            def solve_component(start, fixed_val):
                nonlocal valid_global

                assignments = {start: fixed_val}
                visited_comp = {start}
                valid = True

                queue = [start]
                order = []

                while queue:
                    u = queue.pop(0)
                    order.append(u)

                    for v, c in adj[u]:
                        expected_sum = 1 if c == 1 else 2
                        if v not in assignments:
                            assignments[v] = expected_sum - assignments[u]
                            visited_comp.add(v)
                            queue.append(v)
                        else:
                            # Check constraint consistency
                            if abs(assignments[v] + assignments[u] - expected_sum) > 1e-9:
                                return None, False

                # All reachable nodes assigned, check no undiected nodes with edges
                if valid:
                    return assignments, True
                return None, False

            # Find connected component
            component_nodes = []
            visited = [False] * (N + 1)
            q = [start_node]
            while q:
                u = q.pop(0)
                if not visited[u]:
                    visited[u] = True
                    component_nodes.append(u)
                    for v, c in adj[u]:
                        if not visited[v]:
                            q.append(v)

            # For each component, we can only fix one value and propagate
            # Since all must sum to constraints, need to verify consistency
            comp_assignments = None
            try:
                comp_assignments, success = solve_component(start_node, 0.0)
                if success:
                    # This component is consistent
                    total = sum(abs(v) for v in comp_assignments.values())

                    if total < best_total:
                        best_total = total
                        best_solution = comp_assignments

            except:
                pass
            finally:
                visited = [False] * (N + 1)

        if best_solution is not None and best_total < float('inf'):
            result_values = [best_solution.get(i, 0.0) for i in range(1, N + 1)]
            return "YES\n" + " ".join(f"{v:.2f}" for v in result_values)
        else:
            return "NO"

    except Exception as e:
        return "NO"


