def can_reach(n_adj, n, s, t, excluded):
    """Check if t is reachable from s with excluded edges."""
    visited = [False] * (n + 1)
    queue = [s]
    visited[s] = True
    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        if u == t:
            return True
        for v, edge_idx in n_adj[u]:
            if edge_idx not in excluded and not visited[v]:
                visited[v] = True
                queue.append(v)
    return False

def build_graph(n, m, edges):
    """Build adjacency list from edges. Edges use indices 0 to m-1."""
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v, w, _ = edges[i]
        adj[u].append((v, i))
        adj[v].append((u, i))
    return adj

