def solution(input_string):
    import sys

    input_string = input_string.strip()
    if not input_string:
        return "-1\n"

    lines = input_string.split('\n')
    n, m, k = map(int, lines[0].split())

    edges = []
    road_ids = []
    for i, line in enumerate(lines[1:], start=2):
        parts = line.split()
        if len(parts) >= 3:
            u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((w, u, v))
            road_ids.append(i)

    # Single node case
    if n == 1:
        return "0\n\n"

    # Union-Find
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    def count_components():
        roots = set()
        for i in range(1, n + 1):
            roots.add(find(i))
        return len(roots)

    def is_connected():
        return count_components() == 1

    # Get all edges sorted by weight
    all_edges = []
    for (w, u, v), idx in zip(edges, road_ids):
        all_edges.append((w, u, v, idx))

    all_edges.sort()

    # Select edges for MST, tracking capital edges
    selected = []
    cap_count = 0

    for w, u, v, idx in all_edges:
        if union(u, v):
            selected.append(idx)
            if u == 1 or v == 1:
                cap_count += 1

    # Check if valid
    if cap_count == k and is_connected():
        result = [str(i) for i in sorted(selected)]
        return f"{len(result)}\n{' '.join(result)}\n"

    return "-1\n"

