                    result.append("".join(row_out))
                return '\n'.join(result)

    # If pattern doesn't work, use greedy
    for i in range(n):
        for j in range(m):
            grid_int[i][j] = 0

    grid_int = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid_int[i][j] != 0:
                continue
            used = set()
            for di in range(-1, 2):
                for dj in range(-1, 2):
                    if di == 0 and dj == 0:
