import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return "0"

    # BFS from a to b
    # visited stores the minimum moves to reach each state
    visited = {a: 0}
    queue = collections.deque([a])

    while queue:
        cur = queue.popleft()

        # If we reached b, return the distance
        if cur == b:
            return str(visited[cur])

        d = visited[cur]

        # Check the states that will be added to queue - 
        # if one of them is b, we can return early
        moves = [cur - 1]
        for val in x:
            mod_val = cur % val
            if mod_val > 0:
                moves.append(cur - mod_val)

        for next_state in moves:
            if next_state < b:
                continue
            if next_state not in visited:
                if next_state == b:
                    return str(d + 1)
                visited[next_state] = d + 1
                queue.append(next_state)

    return str(visited[b])


