MOD = 1000000007

def floor_poly_pow(poly_a, N, offset_list):
    """Compute poly_a^N using exponentiation by squaring for finite polynomial."""
    if N == 0:
        result_poly = {0: 1}
    elif N == 1:
        result_poly = poly_a
    else:
        if N % 2 == 0:
            half_res = floor_poly_pow(poly_a, N // 2, offset_list)
            result_poly = multiply_polys(half_res, half_res, offset_list, MOD)
        else:
            half_res = floor_poly_pow(poly_a, N // 2, offset_list)
            full_res = multiply_polys(half_res, half_res, offset_list, MOD)
            result_poly = multiply_polys(full_res, poly_a, offset_list, MOD)
    return result_poly

def multiply_polys(poly1, poly2, offset_list, mod):
    """Multiply two polynomials, return result as dict."""
    max_idx = (len(offset_list) - 1) if offset_list else 0

    result = {}
    for i, c1 in poly1.copy().items():
        if c1 == 0:
            continue
        for j, c2 in poly2.copy().items():
            if c2 == 0:
                continue
            new_idx = i + j
            if new_idx >= len(offset_list):
                result[new_idx] = (result.get(new_idx, 0) + c1 * c2) % mod
            else:
                result[new_idx] = (result.get(new_idx, 0) + c1 * c2) % mod
    return result

def compute_flower_counts(petals, N):
    """Compute ways to get each petal sum with exactly N flowers."""
    if N == 0:
        return {0: 1}

    if N == 1:
        return {p: 1 for p in petals}

    # Use matrix-style DP with optimization
    f = {0: 1}
    for _ in range(N):
        new_f = {}
        for s, count in f.items():
            for p in petals:
                new_s = s + p
                if new_s not in new_f or new_s <= 1000000:
                    new_f[new_s] = (new_f.get(new_s, 0) + count) % MOD
        f = new_f
    return f

def compute_box_counts(chocolates, max_sum):
    """Compute ways to get each chocolate sum with any number of boxes."""
    g = [0] * (max_sum + 1)
    g[0] = 1

    for _ in range(40):  # Enough iterations for reasonable coverage
        for c in chocolates:
            for s in range(max_sum - c, -1, -1):
                if g[s] > 0:
                    g[s + c] = (g[s + c] + g[s]) % MOD

    return g

