def pow_poly(poly, N):
    """Compute poly^N using fast exponentiation."""
    if N == 0:
        return {0: 1}

    result = {0: 1}
    base = poly

    while N > 0:
        if N % 2 == 1:
            result = multiply_filtered_poly(result, base)
        base = multiply_filtered_poly(base, base)
        N //= 2

    return result

def multiply_filtered_poly(poly1, poly2):
    """Multiply polynomials with filtering for reasonable size."""
    MAX_DEGREE = 10000000

    terms = list(poly1.items())
    result = {}

    for idx1, c1 in terms:
        if c1 == 0:
            continue
        for idx2, c2 in poly2.items():
            if c2 == 0:
                continue
            new_idx = idx1 + idx2
            if new_idx <= MAX_DEGREE:
                result[new_idx] = (result.get(new_idx, 0) + c1 * c2) % MOD

    return result

