            elif (b - x) in value_to_index and (b - x) == x:
                # x = b/2, self-referential, always OK for B
                pass
            else:
                # b-x doesn't exist, OK for B
                pass

        if can_in_A and can_in_B:
            comp_to_a[root] = 0
