def backtrack_solution(n, a):
    from math import gcd

    best_seq = None
    best_cost = float('inf')

    # Generate candidates up to 60 (enough for large problems)
    candidates = list(range(1, 61))

    def gcd_valid(seq):
        for i in range(len(seq)):
            for j in range(i + 1, len(seq)):
                if gcd(seq[i], seq[j]) != 1:
                    return False
        return True

    def search(idx, current_seq):
        nonlocal best_seq, best_cost

        if len(current_seq) == n:
            cost = sum(abs(a[i] - current_seq[i]) for i in range(n))
            if cost < best_cost:
                best_cost = cost
                best_seq = current_seq[:]
            return

        # Pruning: check remaining positions can add valid elements
        if len(current_seq) + len(candidates) < n:
            return

        for cand in candidates:
            if gcd_valid(current_seq + [cand]):
                current_seq.append(cand)
                search(idx + 1, current_seq)
                current_seq.pop()

    search(0, [])
    return best_seq

