            # Customer B (100 yuan note): balance decreases by 1 (only if balance > 0)
            if balance > 0:
                new_dp[balance - 1] = (new_dp.get(balance - 1, 0) + count) % MOD

            # Customer C (VIP card): balance unchanged
            new_dp[balance] = (new_dp.get(balance, 0) + count) % MOD

        dp = new_dp

    # Sum up all balances in the range [l, r]
    result = 0
    for b in range(l, min(r + 1, n + 1)):
        result = (result + dp.get(b, 0)) % MOD

    return str(result)

