def verify(p, directions):
    n = len(p)

    for i in range(n):
        # Check if lantern i is illuminated by at least one other lantern
        is_illuminated = False
        for j in range(n):
            if j == i:
                continue
            if p[j] == 0:
                continue

            dj = directions[j]
            if dj == 'R':
                # lantern j illuminates [j+1, j+p[j]]
                if j + 1 <= i <= j + p[j]:
                    is_illuminated = True
                    break
            else:  # dj == 'L'
                # lantern j illuminates [j-p[j], j-1]
                if j - p[j] <= i <= j - 1:
                    is_illuminated = True
                    break

        if not is_illuminated:
            return False

    return True


