def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        if i >= len(lines):
            break
        n, k = map(int, lines[i].split())

        # If K >= N, it's impossible to satisfy constraints
        if k >= n:
            results.append("-1")
            continue

        # Build bipartite graph: position i can use soldier s if |i - s| >= K
        # adj[pos] contains list of valid soldiers for position pos
        adj = [[] for _ in range(n + 1)]
        for pos in range(1, n + 1):
            for s in range(1, n + 1):
                if abs(pos - s) >= k:
                    adj[pos].append(s)
            # Sort to try smaller soldiers first for better lexicographical matching
            adj[pos].sort()

        # Maximum bipartite matching using DFS-based augmenting paths
        match = [0] * (n + 1)  # match[s] = position that uses soldier s

        def dfs(pos, visited):
            """Try to augment matching for position pos"""
            for s in adj[pos]:
                if not visited[s]:
                    visited[s] = True
                    # If soldier s is unused or we can find alternate position
                    if match[s] == 0 or dfs(match[s], visited):
                        match[s] = pos
                        return True
            return False

        # Process each position in order (this helps with lexicographical matching)
        for pos in range(1, n + 1):
            visited = [False] * (n + 1)
            dfs(pos, visited)

        # Check if we got a perfect matching
        if sum(match[1:]) != n:
            results.append("-1")
        else:
            # Build result array where result[pos] = soldier assigned to position pos
            res = [0] * n
            for s in range(1, n + 1):
                pos = match[s]
                res[pos - 1] = s
            results.append(" ".join(map(str, res)))

    return "\n".join(results)


