def solve(n):
    # Memoization dictionary
    memo = {}

    def dp(current):
        # Base case
        if current == 0:
            return 0

        # Check memo
        if current in memo:
            return memo[current]

        # Get unique digits in current number
        digits = {int(d) for d in str(current)}

        # Try all possible subtractions (starting from largest digit for greedy optimization)
        res = float('inf')
        for d in sorted(digits, reverse=True):
            next_val = current - d
            # If this would create a cycle or we've already computed this
            if next_val in memo:
                proceed = True
            else:
                # Check if this path needs exploration or leads to termination
                proceed = True

            if next_val not in memo:
                sub_result = dp(next_val)
                if sub_result != float('inf'):
                    res = min(res, 1 + sub_result)

        memo[current] = res
        return res if res != float('inf') else 0

    return dp(n)

